create database customer_behavior;
use customer_behavior;

select * from customer;

-- Q1. What is total revenue generated by male and female customers ?
select gender,sum(purchase_amount) as revenue from customer
group by gender;

-- Q2. Which customer used discount but still spent more than average purchase amount?
select customer_id , discount_applied from customer
where discount_applied = 'Yes' 
and purchase_amount > ( select avg(purchase_amount) from customer );

-- Q3. which are top 5 products with highest average review rating ?
select item_purchased , round(avg(review_rating),2) from customer
group by item_purchased
order by avg(review_rating) desc limit 5;

-- Q4. compare the average purchase amount between express and standard shipping
select shipping_type,round(avg(purchase_amount),2) from customer
where shipping_type in ('Standard','Express')
group by shipping_type;

-- Q5. Do subscribed spends more ? compare average spends and total revenue between subscribed and unsubscribed customers?
select 
subscription_status,
count(customer_id) as no_customer,
round(avg(purchase_amount),2) as average_spends,
sum(purchase_amount) as total_revenue
from customer
group by subscription_status;

-- Q6.Which 5 products has the highest percentage of purchase with discount applied ?
select item_purchased ,
round(100*sum(case when discount_applied = 'Yes' then 1 end)/count(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc limit 5;

-- Q7. segment customers into New,Returning and loyal based on their total number of previous
-- purchases, and show the count of each segment.
with customer_type as (
select  customer_id,previous_purchases,
case  
     when previous_purchases = 1 then 'new'
     when previous_purchases between 2 and 10 then 'returning'
     else 'loyal' 
     end as customer_segment from customer
     )
select customer_segment,count(*) as number_customer from customer_type
group by customer_segment;

-- Q8. what are top 3 purchased products within each category
WITH item_counts AS (
    SELECT category, item_purchased, COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category 
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank,category,item_purchased,total_orders
FROM item_counts
WHERE item_rank <= 3;

-- Q9. Customer who are repeat buyers (More than 5 previous purchase) also likely to subscribes ?
select subscription_status , count(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status;

-- Q10.What is the revenue contribution of each age group ?
select age_group, sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;